-- Synthetic local DB contract/attack suite. All fixture changes rolled back.
\set ON_ERROR_STOP on
begin;
create function pg_temp.assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label; end if; end$$;
create function pg_temp.reject(q text,code text) returns void language plpgsql as $$begin begin execute q; exception when others then if sqlstate=code then return; end if; raise; end; raise exception 'FAIL accepted %',q;end$$;
create temp table flow_results(key text primary key,v jsonb);
grant all on flow_results to service_role;
insert into auth.users(id,email) values('11111111-1111-4111-8111-111111111111','owner@example.test'),('22222222-2222-4222-8222-222222222222','staff@example.test'),('33333333-3333-4333-8333-333333333333','other@example.test'),('44444444-4444-4444-8444-444444444444','admin@example.test');
insert into public.tenants(id,name,slug,timezone,currency) values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','A','w3-a','UTC','USD'),('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','B','w3-b','UTC','USD');
insert into public.tenant_members(tenant_id,user_id,role) values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','11111111-1111-4111-8111-111111111111','BUSINESS_OWNER'),('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','22222222-2222-4222-8222-222222222222','BUSINESS_STAFF'),('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','33333333-3333-4333-8333-333333333333','BUSINESS_OWNER');
insert into public.platform_admins(user_id) values('44444444-4444-4444-8444-444444444444');
insert into public.services(id,tenant_id,archetype,name,currency,base_price) values('a0000000-0000-4000-8000-000000000001','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','simple','A service','USD',0),('b0000000-0000-4000-8000-000000000001','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','simple','B service','USD',0);
insert into public.service_questions(tenant_id,service_id,question_key,prompt,kind,unit_price,min_qty,max_qty,choices) values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','a0000000-0000-4000-8000-000000000001','count','How many?','quantity',0,1,5,'[]'),('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','a0000000-0000-4000-8000-000000000001','type','Which type?','single_choice',null,null,null,'[{"id":"old","label":"Original","priceDelta":0}]');
insert into public.service_questions(tenant_id,service_id,question_key,prompt,kind,unit_price,min_qty,max_qty,choices) values('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','b0000000-0000-4000-8000-000000000001','count','How many?','quantity',0,1,5,'[]'),('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','b0000000-0000-4000-8000-000000000001','type','Which type?','single_choice',null,null,null,'[{"id":"old","label":"Original","priceDelta":0}]');
update public.service_questions set required=false where question_key='count';
insert into public.service_questions(tenant_id,service_id,question_key,prompt,kind,required,choices) values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','a0000000-0000-4000-8000-000000000001','tags','Options','multi_choice',false,'[{"id":"z","label":"Z"},{"id":"a","label":"A"}]');
insert into flow_results values('authoring','{"authoringVersion":2,"config":{"key":"generic","steps":[{"key":"type","questionKey":"type","kind":"question","required":true},{"key":"tags","questionKey":"tags","kind":"question","required":false},{"key":"count","questionKey":"count","kind":"question","required":true,"visibleWhen":{"field":"tags","op":"includes","value":"z"}}]},"questionOverrides":{"count":{"minQty":2,"maxQty":4},"type":{"prompt":"Your type"}}}');
create function pg_temp.save(actor uuid,tenant uuid,revision bigint) returns jsonb language sql as $$select public.save_configurable_flow_draft(actor,tenant,'a0000000-0000-4000-8000-000000000002','a0000000-0000-4000-8000-000000000001',revision,'Configurable',(select v from flow_results where key='authoring'))$$;
create function pg_temp.publish(revision bigint) returns jsonb language sql as $$select public.publish_configurable_flow('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','a0000000-0000-4000-8000-000000000002',revision,'a0000000-0000-4000-8000-000000000003','a0000000-0000-4000-8000-000000000004','["https://business.example"]')$$;
create function pg_temp.submit(answers jsonb) returns jsonb language sql as $$select public.submit_flow_request(repeat('a',64),'https://business.example','request-key-00000001',answers,'{"name":"Test Person","email":"person@example.test"}','2099-01-01T10:00Z')$$;
set local role service_role;
select pg_temp.reject($q$select pg_temp.save('22222222-2222-4222-8222-222222222222','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',0)$q$,'42501');
select pg_temp.reject($q$select pg_temp.save('44444444-4444-4444-8444-444444444444','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',0)$q$,'42501');
select pg_temp.reject($q$select pg_temp.save('33333333-3333-4333-8333-333333333333','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',0)$q$,'42501');
select pg_temp.reject($q$select pg_temp.save('33333333-3333-4333-8333-333333333333','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',0)$q$,'P0002');
select pg_temp.assert(pg_temp.save('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',0)->'authoringVersion'='2','V2 save marker');
select pg_temp.reject($q$select pg_temp.save('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',0)$q$,'23505');
select pg_temp.reject($q$select pg_temp.save('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',2)$q$,'40001');
select pg_temp.assert(jsonb_array_length(public.flow_owner_list('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa')->'flows')=0,'legacy list excludes V2');
select pg_temp.assert(jsonb_array_length(public.flow_owner_configurable_list('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa')->'flows')=1,'V2 list');
select pg_temp.assert(jsonb_array_length(public.flow_owner_configurable_list('33333333-3333-4333-8333-333333333333','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb')->'flows')=0,'other tenant list');
select pg_temp.reject($q$select public.flow_owner_draft('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','a0000000-0000-4000-8000-000000000002')$q$,'P0002');
insert into flow_results values('draft',public.get_configurable_flow_draft('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','a0000000-0000-4000-8000-000000000002'));
select pg_temp.assert((select v->'authoring'=(select v from flow_results where key='authoring') and v->'effectiveService'->'questions'->0->>'prompt'='Your type' from flow_results where key='draft'),'roundtrip and effective prompt');
select pg_temp.reject($q$select public.save_bound_flow_draft('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','a0000000-0000-4000-8000-000000000002','a0000000-0000-4000-8000-000000000001',1,'Downgrade',(select v->'config' from flow_results where key='authoring'))$q$,'0A000');
select pg_temp.reject($q$select public.publish_bound_flow('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','a0000000-0000-4000-8000-000000000002',1,'a0000000-0000-4000-8000-000000000003','a0000000-0000-4000-8000-000000000004','["https://business.example"]')$q$,'0A000');
select pg_temp.reject($q$select public.publish_flow_version('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','a0000000-0000-4000-8000-000000000002',1,'a0000000-0000-4000-8000-000000000003','a0000000-0000-4000-8000-000000000004',(select v->'config' from flow_results where key='authoring'),'["https://business.example"]')$q$,'0A000');
reset role;
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
set local role authenticated;
select pg_temp.reject($q$select public.save_flow_draft('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','a0000000-0000-4000-8000-000000000002','Downgrade',1,'{"key":"v1","steps":[{"key":"type","questionKey":"type"}]}')$q$,'0A000');
reset role;
select pg_temp.reject($q$update public.flow_drafts set authoring='{}' where flow_id='a0000000-0000-4000-8000-000000000002'$q$,'23514');
select pg_temp.reject($q$insert into public.flow_versions(id,tenant_id,flow_id,source_revision,submission_mode,config,render_schema_version,configurable_snapshot) select 'c0000000-0000-4000-8000-000000000003',tenant_id,flow_id,revision,'unconfirmed_request',config,2,'{}' from public.flow_drafts$q$,'23514');
set local role service_role;
select pg_temp.reject($q$select pg_temp.publish(2)$q$,'40001');
select pg_temp.assert(pg_temp.publish(1)->'renderSchemaVersion'='2','publication marker');
select pg_temp.reject($q$select pg_temp.publish(1)$q$,'23505');
insert into flow_results values('session',public.issue_flow_session('a0000000-0000-4000-8000-000000000004',repeat('a',64),'https://business.example'));
select pg_temp.assert((select v->'render'->'renderSchemaVersion'='2' and v->'render'->>'submissionMode'='unconfirmed_request' from flow_results where key='session'),'stored render dispatch');
select pg_temp.reject($q$select pg_temp.submit('{"type":{"choiceIds":["old"]},"tags":{"choiceIds":["z"]}}')$q$,'22023');
select pg_temp.reject($q$select pg_temp.submit('{"type":{"choiceIds":["old"]},"count":{"quantity":2}}')$q$,'22023');
insert into flow_results values('receipt',pg_temp.submit('{"type":{"choiceIds":["old"]},"tags":{"choiceIds":["a","z"]},"count":{"quantity":3}}'));
select pg_temp.assert(pg_temp.submit('{"type":{"choiceIds":["old"]},"tags":{"choiceIds":["z","a"]},"count":{"quantity":3}}')=(select v from flow_results where key='receipt'),'canonical set retry');
select pg_temp.reject($q$select pg_temp.submit('{"type":{"choiceIds":["old"]},"tags":{"choiceIds":["z"]},"count":{"quantity":3}}')$q$,'40001');
reset role;
select pg_temp.assert((select selection->'answers'->'tags'->'choiceIds'='["z","a"]' and state='draft' and pricing='{}' and payment_id is null from public.bookings),'canonical stored no-payment request');
select pg_temp.assert((select count(*)=1 from public.flow_requests) and (select count(*)=1 from public.durable_outbox) and (select count(*)=0 from public.capacity_holds) and (select count(*)=0 from public.resource_reservations),'one effect and no holds');
update public.service_questions set prompt='Changed catalog',max_qty=2 where question_key='count';
set local role service_role;
select pg_temp.assert(pg_temp.submit('{"type":{"choiceIds":["old"]},"tags":{"choiceIds":["z","a"]},"count":{"quantity":3}}')=(select v from flow_results where key='receipt'),'immutable snapshot survives catalog change');
reset role;
select pg_temp.reject($q$update public.flow_versions set render_schema_version=1,configurable_snapshot=null$q$,'55000');
update public.flow_sessions set revoked=true;
set local role service_role;
select pg_temp.reject($q$select pg_temp.submit('{"type":{"choiceIds":["old"]},"tags":{"choiceIds":["z","a"]},"count":{"quantity":3}}')$q$,'42501');
reset role;
update public.flow_sessions set revoked=false,expires_at=clock_timestamp()-interval '1 second';
set local role service_role;
select pg_temp.reject($q$select pg_temp.submit('{"type":{"choiceIds":["old"]},"tags":{"choiceIds":["z","a"]},"count":{"quantity":3}}')$q$,'42501');
reset role;
-- New V2 effect must roll back if the durable outbox transaction fails.
update public.services set active=true;
create function pg_temp.outbox_fail() returns trigger language plpgsql as $$begin raise exception 'INJECTED_OUTBOX_FAILURE';end$$;
create trigger configurable_test_outbox_failure before insert on public.durable_outbox for each row execute function pg_temp.outbox_fail();
set local role service_role;
select public.issue_flow_session('a0000000-0000-4000-8000-000000000004',repeat('b',64),'https://business.example');
select pg_temp.reject($q$select public.submit_flow_request(repeat('b',64),'https://business.example','rollback-key-000001','{"type":{"choiceIds":["old"]}}','{"name":"Other","email":"rollback@example.test"}','2099-01-01T10:00Z')$q$,'P0001');
reset role;
select pg_temp.assert((select count(*)=1 from public.bookings) and (select count(*)=1 from public.flow_requests) and (select count(*)=1 from public.durable_outbox) and not exists(select 1 from public.customers where email='rollback@example.test'),'outbox rollback includes customer and request');
drop trigger configurable_test_outbox_failure on public.durable_outbox;
update public.tenants set status='suspended' where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa';
set local role service_role;
select pg_temp.reject($q$select pg_temp.save('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',1)$q$,'42501');
select pg_temp.reject($q$select pg_temp.publish(1)$q$,'42501');
reset role;
update public.tenants set status='active' where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa';
update public.tenant_members set role='BUSINESS_STAFF' where user_id='11111111-1111-4111-8111-111111111111';
set local role service_role;
select pg_temp.reject($q$select pg_temp.save('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',1)$q$,'42501');
reset role;
select pg_temp.assert((select bool_and(relrowsecurity and relforcerowsecurity) from pg_class where oid in('public.flow_drafts'::regclass,'public.flow_versions'::regclass)),'forced RLS retained');
select pg_temp.assert(not has_table_privilege('service_role','public.flow_drafts','UPDATE') and not has_table_privilege('authenticated','public.flow_versions','INSERT') and not has_table_privilege('anon','public.flow_drafts','SELECT'),'raw privilege boundary');
select pg_temp.assert(not has_function_privilege('authenticated','public.save_configurable_flow_draft(uuid,uuid,uuid,uuid,bigint,text,jsonb)','EXECUTE') and not has_function_privilege('anon','public.flow_owner_configurable_list(uuid,uuid)','EXECUTE'),'RPC execution boundary');
rollback;
\echo CONFIGURABLE FLOW SQL TESTS PASS
